import{_ as r,c as t,o,a5 as a}from"./chunks/framework.DqXSAjBk.js";const u=JSON.parse('{"title":"Reports","description":"","frontmatter":{},"headers":[],"relativePath":"apps/cloud/reports.md","filePath":"apps/cloud/reports.md"}'),i={name:"apps/cloud/reports.md"};function s(n,e,l,p,d,c){return o(),t("div",{"data-pagefind-body":!0},e[0]||(e[0]=[a('<h1 id="reports" tabindex="-1">Reports <a class="header-anchor" href="#reports" aria-label="Permalink to &quot;Reports&quot;">​</a></h1><p>A core feature of the cloud interface, reports allow you to view and download detailed information about your devices.</p><figure><img src="https://upload.r2.lb.chasm.cloud/2025/10/imgur/mwffaBW.png" alt="" tabindex="0"><figcaption></figcaption></figure><p>All reports are generated instantly and for any custom time period, and for any set of devices.</p><p>You can also export reports, or schedule them to be sent to you via email.</p><h2 id="general-reports" tabindex="-1">General Reports <a class="header-anchor" href="#general-reports" aria-label="Permalink to &quot;General Reports&quot;">​</a></h2><ul><li><a href="./reports/status">Status Report</a>: Quick overview of current device status. Includes last connection, battery, current position and more.</li><li><a href="./reports/route">Route Report</a>: List of all the points transmitted by the device with street address, speed and course.</li><li><a href="./reports/trip-summary">Trip Summary</a>: Summary view of trips made, showing start and end location, time, distance and duration.</li><li><a href="./reports/detailed-trip">Detailed Trip</a>: A more detailed version of the Trip Summary report showing every street address visited by the device.</li><li><a href="./reports/distance">Distance Report</a>: Report of distance travelled between two dates.</li><li><a href="./reports/speeding">Speeding Report</a>: Quickly identify devices that have gone over a given speed limit.</li></ul><h2 id="zone-reports" tabindex="-1">Zone Reports <a class="header-anchor" href="#zone-reports" aria-label="Permalink to &quot;Zone Reports&quot;">​</a></h2><ul><li><a href="./reports/zone-by-time">Zone Report (by Time)</a>: Report of devices in zones over time.</li><li><a href="./reports/specific-zone">Specific Zone Report</a>: Check entries and exits for given zone(s).</li><li><a href="./reports/live-zones">Live Zone Status</a>: Simple dashboard that groups devices by current zone or zone type.</li><li><a href="./reports/trip-count">Trip Count</a>: Count the number of trips between two zones (or zone types).</li><li><a href="./reports/zone-aggregate">Aggregated Zone Report</a></li><li><a href="./reports/inventory">Inventory Report</a></li></ul><h2 id="vehicle-reports" tabindex="-1">Vehicle Reports <a class="header-anchor" href="#vehicle-reports" aria-label="Permalink to &quot;Vehicle Reports&quot;">​</a></h2><ul><li><a href="./reports/vehicle-activity">Vehicle Activity</a>: Report of device motion relative to ignition and working hours.</li><li><a href="./reports/vehicle-summary">Vehicle Summary</a>: Report of vehicle trips, distances, utilisation and more.</li><li><a href="./reports/vehicle-events">Vehicle Events</a>: Text log of vehicle events, including zone entry &amp; exit, ignition on &amp; off and more</li></ul><h2 id="sensor-reports" tabindex="-1">Sensor Reports <a class="header-anchor" href="#sensor-reports" aria-label="Permalink to &quot;Sensor Reports&quot;">​</a></h2><ul><li><a href="./reports/temperature">Temperature Report</a></li><li><a href="./reports/proximity">Proximity Report</a></li><li><a href="./reports/battery-performance">Battery Performance Report</a></li><li><a href="./reports/motion-data">Motion Data Report</a></li></ul><p>For a high level overview of some reports, <a href="https://lightbug.io/user_manual.pdf" target="_blank" rel="noreferrer">see page 65 of the legacy user manual</a></p>',14)]))}const f=r(i,[["render",s]]);export{u as __pageData,f as default};
